const b = $json.body ?? {};
if (!b.company_id || !b.payload?.from_number || !b.payload?.to_number) {
  return [{ json: { _error: { code: 'invalid_input', message: 'company_id, payload.from_number, payload.to_number required', retryable: false } } }];
}
return [{ json: {
  company_id: b.company_id,
  request_id: b.request_id ?? crypto.randomUUID(),
  source: 'webhook',
  channel: 'voice',
  payload: { from_number: String(b.payload.from_number), to_number: String(b.payload.to_number) },
  started_at: Date.now(),
} }];

// Decide: is recovery enabled, and are we inside quiet hours (company timezone)?
const base = $('Validate').first().json;
const ctx = $json.data?.ctx ?? {};
const enabled = ctx.modules?.missed_call_recovery !== false;

const tz = ctx.company?.timezone ?? $env.TK_DEFAULT_TIMEZONE;
const now = new Date().toLocaleTimeString('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false });
const qh = ctx.quiet_hours ?? ctx.compliance?.quiet_hours ?? { start: '21:00', end: '08:00' };
const inQuietHours = qh.start > qh.end ? (now >= qh.start || now < qh.end) : (now >= qh.start && now < qh.end);

// Template with variables — from config, never hardcoded copy.
const template = ctx.templates?.missed_call_sms
  ?? "Hi! This is {{company_name}} — sorry we missed your call. How can we help? Reply here and we'll take care of you, or tell us a good time to call back.";
const sms_body = template.replace(/{{\s*company_name\s*}}/g, ctx.company?.name ?? '');

return [{ json: { ...base, ctx: { company: ctx.company }, enabled, inQuietHours, sms_body, sender_number: base.payload.to_number } }];
